<form method="post" action="<?=e(url($savePath))?>" class="journey-form journey-episode-form">
  <?=csrf_field()?><input type="hidden" name="action" value="save_episode"><input type="hidden" name="episode_id" value="<?=e(journeys_field($episodeForm,'episode_id',journeys_field($episodeForm,'id')))?>">
  <div class="journey-fields-two"><div class="field"><label for="<?=e($formKey)?>-post">Post ID</label><input id="<?=e($formKey)?>-post" name="post_id" inputmode="numeric" pattern="[1-9][0-9]*" list="journey-post-options" required value="<?=e(journeys_field($episodeForm,'post_id'))?>"><small class="journey-help">Find the number in a post’s Writer edit address. Recent posts also appear as suggestions.</small></div><div class="field"><label for="<?=e($formKey)?>-order">Chapter number</label><input id="<?=e($formKey)?>-order" name="episode_order" type="number" min="1" max="9999" required value="<?=e(journeys_field($episodeForm,'episode_order'))?>"></div></div>
  <div class="field"><label for="<?=e($formKey)?>-summary">Public chapter summary <span class="optional">(optional)</span></label><textarea id="<?=e($formKey)?>-summary" name="public_summary" rows="3" maxlength="600"><?=e(journeys_field($episodeForm,'public_summary'))?></textarea><small class="journey-help">Uses the post’s standfirst if left blank.</small></div>
  <div class="field"><label for="<?=e($formKey)?>-basis">Evidence basis</label><select id="<?=e($formKey)?>-basis" name="evidence_basis"><?php foreach(journeys_evidence_bases() as $key=>$label):?><option value="<?=e($key)?>" <?=journeys_field($episodeForm,'evidence_basis','author_experience')===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></div>
  <div class="field"><label for="<?=e($formKey)?>-evidence">Public evidence note <span class="optional">(optional)</span></label><textarea id="<?=e($formKey)?>-evidence" name="evidence_summary" rows="3" maxlength="2000"><?=e(journeys_field($episodeForm,'evidence_summary'))?></textarea><small class="journey-help">Shown beside the chapter. Explain the source, period and limits of claims without disclosing confidential records.</small></div>
  <div class="field"><label for="<?=e($formKey)?>-private">Private evidence notes <span class="optional">(optional)</span></label><textarea id="<?=e($formKey)?>-private" name="private_evidence_notes" rows="4" maxlength="12000"><?=e(journeys_field($episodeForm,'private_evidence_notes'))?></textarea><small class="journey-help">Kept in the Writer record. These notes are not used in public chapter summaries.</small></div>
  <label class="journey-check"><input type="checkbox" name="is_published" value="1" <?=journeys_checked($episodeForm['is_published']??null)?'checked':''?>><span>Show this chapter when the journey and linked post are published.</span></label>
  <button class="wbtn primary" type="submit">Save chapter link</button>
</form>
